def checkout(session, account, payload, now, store):
    if session is None:
        return {"status": 401}
    if session["account"] != account or "purchase" not in session["scopes"]:
        return {"status": 403}
    note = payload.get("note") or "default"
    purchase = store.record(account, payload["key"], note)
    return {"status": 202, "account": account, "purchase": purchase, "note": note}

