def publish_pending(db, bus):
    for event in db.pending_outbox():
        bus.send(event["event_id"], event["payload"])
        db.mark_sent(event["event_id"])

def notify(event, remote):
    for attempt in range(3):
        try:
            remote.send(event, timeout=1)
            return {"ok": True}
        except TimeoutError:
            continue
    return {"ok": True}

