from checkout import checkout

def test_null_note(fake_store):
    session = {"account": "0042", "scopes": ["purchase"], "expires_at": 10}
    result = checkout(session, "0042", {"key": "abc", "note": None}, 1, fake_store)
    assert result["status"] == 202
